1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"sort"
8		"strings"
9	)
10	
11	type orderResponse struct {
12		Valid  bool              `json:"valid"`
13		Errors []validationError `json:"errors"`
14		Order  []string          `json:"order"`
15	}
16	
17	// handleOrderConfiguration returns a deterministic topological order over
18	// the resources of an already-valid configuration document.
19	func handleOrderConfiguration(w http.ResponseWriter, r *http.Request) {
20		w.Header().Set("Content-Type", "application/json; charset=utf-8")
21		if r.Method != http.MethodPost {
22			w.Header().Set("Allow", http.MethodPost)
23			w.WriteHeader(http.StatusMethodNotAllowed)
24			_ = json.NewEncoder(w).Encode(map[string]any{
25				"error": map[string]string{"code": "method_not_allowed"},
26			})
27			return
28		}
29	
30		doc, ok := decodeConfigurationBody(w, r)
31		if !ok {
32			return
33		}
34	
35		// Dependencies are only interpreted once the base document is valid.
36		baseErrs := validateConfiguration(doc)
37		if len(baseErrs) != 0 {
38			sortValidationErrors(baseErrs)
39			writeValidation(w, http.StatusUnprocessableEntity, baseErrs)
40			return
41		}
42	
43		order, depErrs := orderConfiguration(doc)
44		if len(depErrs) != 0 {
45			sortValidationErrors(depErrs)
46			writeValidation(w, http.StatusUnprocessableEntity, depErrs)
47			return
48		}
49	
50		w.WriteHeader(http.StatusOK)
51		_ = json.NewEncoder(w).Encode(orderResponse{
52			Valid:  true,
53			Errors: []validationError{},
54			Order:  order,
55		})
56	}
57	
58	// orderConfiguration interprets the dependsOn fields of a validated document.
59	// It returns every dependency problem in one pass; dependency problems take
60	// precedence over cycle detection, and cycles take precedence over ordering.
61	func orderConfiguration(doc any) ([]string, []validationError) {
62		root := doc.(map[string]any)
63		resourceEntries := root["resources"].([]any)
64	
65		addresses := make([]string, len(resourceEntries))
66		known := make(map[string]bool, len(resourceEntries))
67		dependsOn := make([][]string, len(resourceEntries))
68		for i, entry := range resourceEntries {
69			address := entry.(map[string]any)["address"].(string)
70			addresses[i] = address
71			known[address] = true
72		}
73	
74		var errs []validationError
75		add := func(code, message, path string) {
76			errs = append(errs, validationError{Code: code, Message: message, Path: path})
77		}
78		for i, entry := range resourceEntries {
79			obj := entry.(map[string]any)
80			raw, present := obj["dependsOn"]
81			if !present {
82				continue
83			}
84			fieldPath := fmt.Sprintf("/resources/%d/dependsOn", i)
85			arr, ok := raw.([]any)
86			if !ok {
87				add(codeInvalidDocument, `"dependsOn" must be an array of non-empty resource address strings`, fieldPath)
88				continue
89			}
90			seen := map[string]bool{}
91			for j, el := range arr {
92				elPath := fmt.Sprintf("%s/%d", fieldPath, j)
93				ref, isString := el.(string)
94				if !isString || ref == "" {
95					add(codeInvalidDocument, "dependency must be a non-empty resource address string", elPath)
96					continue
97				}
98				if seen[ref] {
99					add(codeDuplicateDependency, fmt.Sprintf("duplicate dependency %q", ref), elPath)
100					continue
101				}
102				seen[ref] = true
103				switch {
104				case ref == addresses[i]:
105					add(codeSelfDependency, "resource must not depend on itself", elPath)
106				case !known[ref]:
107					add(codeUnknownDependency, fmt.Sprintf("unknown dependency %q", ref), elPath)
108				default:
109					dependsOn[i] = append(dependsOn[i], ref)
110				}
111			}
112		}
113		if len(errs) != 0 {
114			return nil, errs
115		}
116	
117		if cyclic := cyclicResources(addresses, dependsOn); cyclic != nil {
118			sort.Strings(cyclic)
119			errs = append(errs, validationError{
120				Code:    codeDependencyCycle,
121				Message: "dependency cycle: " + strings.Join(cyclic, ", "),
122				Path:    "/resources",
123			})
124			return nil, errs
125		}
126	
127		return topologicalOrder(addresses, dependsOn), nil
128	}
129	
130	// topologicalOrder performs Kahn's algorithm, always selecting the available
131	// resource with the smallest address (Unicode code point order), so documents
132	// differing only in equivalent dependsOn permutations order identically.
133	func topologicalOrder(addresses []string, dependsOn [][]string) []string {
134		dependents := make(map[string][]string, len(addresses))
135		indegree := make(map[string]int, len(addresses))
136		for _, address := range addresses {
137			indegree[address] = 0
138		}
139		for i, deps := range dependsOn {
140			indegree[addresses[i]] = len(deps)
141			for _, dep := range deps {
142				dependents[dep] = append(dependents[dep], addresses[i])
143			}
144		}
145	
146		var ready []string
147		for _, address := range addresses {
148			if indegree[address] == 0 {
149				ready = append(ready, address)
150			}
151		}
152	
153		order := make([]string, 0, len(addresses))
154		for len(ready) > 0 {
155			sort.Strings(ready)
156			next := ready[0]
157			ready = ready[1:]
158			order = append(order, next)
159			for _, dependent := range dependents[next] {
160				indegree[dependent]--
161				if indegree[dependent] == 0 {
162					ready = append(ready, dependent)
163				}
164			}
165		}
166		return order
167	}
168	
169	// cyclicResources returns the addresses that actually lie on a dependency
170	// cycle. Resources that merely depend, directly or indirectly, on a cycle
171	// without being part of one are excluded. Self-loops cannot occur because
172	// self dependencies are rejected beforehand.
173	func cyclicResources(addresses []string, dependsOn [][]string) []string {
174		index := make(map[string]int, len(addresses))
175		for i, address := range addresses {
176			index[address] = i
177		}
178	
179		// Tarjan's strongly connected components algorithm, iteratively to
180		// avoid recursion-depth concerns on long dependency chains.
181		indices := make([]int, len(addresses))
182		lowlink := make([]int, len(addresses))
183		onStack := make([]bool, len(addresses))
184		for i := range indices {
185			indices[i] = -1
186		}
187		var stack []int
188		var nextIndex int
189		var cyclic []string
190	
191		type frame struct {
192			v    int
193			edge int
194		}
195		for root := range addresses {
196			if indices[root] != -1 {
197				continue
198			}
199			indices[root] = nextIndex
200			lowlink[root] = nextIndex
201			nextIndex++
202			stack = append(stack, root)
203			onStack[root] = true
204			work := []frame{{v: root}}
205			for len(work) > 0 {
206				top := len(work) - 1
207				v := work[top].v
208				if work[top].edge < len(dependsOn[v]) {
209					w := index[dependsOn[v][work[top].edge]]
210					work[top].edge++
211					if indices[w] == -1 {
212						indices[w] = nextIndex
213						lowlink[w] = nextIndex
214						nextIndex++
215						stack = append(stack, w)
216						onStack[w] = true
217						work = append(work, frame{v: w})
218						continue
219					}
220					if onStack[w] && indices[w] < lowlink[v] {
221						lowlink[v] = indices[w]
222					}
223					continue
224				}
225				if lowlink[v] == indices[v] {
226					var component []string
227					for {
228						w := stack[len(stack)-1]
229						stack = stack[:len(stack)-1]
230						onStack[w] = false
231						component = append(component, addresses[w])
232						if w == v {
233							break
234						}
235					}
236					// With self-loops rejected, a component of two or more
237					// nodes is exactly a cycle.
238					if len(component) > 1 {
239						cyclic = append(cyclic, component...)
240					}
241				}
242				work = work[:len(work)-1]
243				if len(work) > 0 {
244					if parent := work[len(work)-1].v; lowlink[v] < lowlink[parent] {
245						lowlink[parent] = lowlink[v]
246					}
247				}
248			}
249		}
250		return cyclic
251	}
